#include <iostream>
#include <memory>

class Shape {
public:
    virtual void draw() const = 0; // Pure virtual function
    virtual ~Shape() = default;
};

class Circle : public Shape {
public:
    void draw() const override { std::cout << "Drawing Circle\n"; }
};

class Rectangle : public Shape {
public:
    void draw() const override { std::cout << "Drawing Rectangle\n"; }
};

int main() {
    std::unique_ptr<Shape> s1 = std::make_unique<Circle>();
    std::unique_ptr<Shape> s2 = std::make_unique<Rectangle>();
    s1->draw();
    s2->draw();
    return 0;
}

#include <iostream>

class Complex {
private:
    double real, imag;
public:
    Complex(double r = 0, double i = 0) : real(r), imag(i) {}
    Complex operator+(const Complex& other) const {
        return Complex(real + other.real, imag + other.imag);
    }
    void print() const { std::cout << real << " + " << imag << "i\n"; }
};

int main() {
    Complex c1(3.5, 2.5), c2(1.5, 4.5);
    Complex c3 = c1 + c2;
    std::cout << "Sum: "; c3.print();
    return 0;
}

#include <iostream>
#include <unordered_map>
#include <list>

class LRUCache {
    int capacity;
    std::list<std::pair<int, int>> items;
    std::unordered_map<int, std::list<std::pair<int, int>>::iterator> map;
public:
    LRUCache(int cap) : capacity(cap) {}
    int get(int key) {
        if (map.find(key) == map.end()) return -1;
        items.splice(items.begin(), items, map[key]);
        return map[key]->second;
    }
    void put(int key, int val) {
        if (map.find(key) != map.end()) {
            items.splice(items.begin(), items, map[key]);
            map[key]->second = val;
            return;
        }
        if (items.size() == capacity) {
            map.erase(items.back().first);
            items.pop_back();
        }
        items.emplace_front(key, val);
        map[key] = items.begin();
    }
};

int main() {
    LRUCache cache(2);
    cache.put(1, 10);
    cache.put(2, 20);
    std::cout << "Get 1: " << cache.get(1) << "\n";
    cache.put(3, 30); // evicts key 2
    std::cout << "Get 2: " << cache.get(2) << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <queue>

void bfs(int start, const std::vector<std::vector<int>>& adj, int n) {
    std::vector<bool> visited(n, false);
    std::queue<int> q;
    visited[start] = true; q.push(start);
    std::cout << "BFS: ";
    while (!q.empty()) {
        int u = q.front(); q.pop();
        std::cout << u << " ";
        for (int v : adj[u]) {
            if (!visited[v]) { visited[v] = true; q.push(v); }
        }
    }
    std::cout << "\n";
}

int main() {
    int n = 5;
    std::vector<std::vector<int>> adj(n);
    adj[0] = {1, 2}; adj[1] = {0, 3}; adj[2] = {0, 4}; adj[3] = {1}; adj[4] = {2};
    bfs(0, adj, n);
    return 0;
}
